-- 023 Exames/ASO postflight. Execute COMPLETE file as trusted SQL Editor auditor.
-- Read-only; no corrections, impersonation, signed URLs or file-content access.
-- Save ALL result sets. Pre/post preservation fingerprints MUST match before application deployment.
-- Fixed counts reflect approved inventory: changes since inventory require review, never automatic cleanup.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
WITH actual AS (WITH entries AS (
 SELECT 'relation:'||c.oid::regclass::text identity,jsonb_build_object('rls',c.relrowsecurity,'options',c.reloptions) detail
 FROM pg_class c WHERE c.oid IN (to_regclass('public.documentos'),to_regclass('public.exames_catalogo'),to_regclass('public.vw_dashboard_documentos'),to_regclass('storage.objects'))
 UNION ALL SELECT 'policy:'||schemaname||'.'||tablename||'.'||policyname,
 jsonb_build_object('permissive',permissive,'roles',roles::text,'command',cmd,'using',qual,'check',with_check)
 FROM pg_policies WHERE (schemaname='public' AND tablename IN ('documentos','exames_catalogo'))
 OR (schemaname='storage' AND tablename='objects' AND policyname LIKE 'documentos_%')
 UNION ALL SELECT 'function:'||p.oid::regprocedure::text,
 jsonb_build_object('hash',md5(replace(p.prosrc,E'\r\n',E'\n')),'definer',p.prosecdef,'config',p.proconfig,
 'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),
 'owner',pg_get_userbyid(p.proowner),'owner_privileged',(SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE oid=p.proowner),
 'authenticated_owner_member',pg_has_role('authenticated',p.proowner,'MEMBER'),'anon_owner_member',pg_has_role('anon',p.proowner,'MEMBER'),
 'volatility',p.provolatile,'return_type',p.prorettype::regtype::text)
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='engmarq_private'
 AND p.proname IN ('can_access_catalogos','can_access_documento_row','can_access_documento','guard_documento_metadata',
 'guard_documento_reference','guard_aso_write','can_read_exames_catalogo')
 UNION ALL SELECT 'trigger:'||tgname,jsonb_build_object('definition',pg_get_triggerdef(oid),'enabled',tgenabled)
 FROM pg_trigger WHERE tgrelid=to_regclass('public.documentos') AND NOT tgisinternal
 UNION ALL SELECT 'constraint:'||conname,jsonb_build_object('definition',pg_get_constraintdef(oid),'validated',convalidated)
 FROM pg_constraint WHERE conrelid=to_regclass('public.documentos')
 UNION ALL SELECT 'view:vw_dashboard_documentos',jsonb_build_object('definition',pg_get_viewdef(oid))
 FROM pg_class WHERE oid=to_regclass('public.vw_dashboard_documentos')
 UNION ALL SELECT 'column:documentos.'||a.attname,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull)
 FROM pg_attribute a WHERE a.attrelid=to_regclass('public.documentos') AND a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'grant:'||c.oid::regclass::text||'.'||r.role,
 jsonb_build_object('select',has_table_privilege(r.role,c.oid,'SELECT'),
 'delete',has_table_privilege(r.role,c.oid,'DELETE'),
 'insert',ARRAY(SELECT attname FROM pg_attribute a WHERE a.attrelid=c.oid AND attnum>0 AND NOT attisdropped AND has_column_privilege(r.role,c.oid,a.attname,'INSERT') ORDER BY attname),
 'update',ARRAY(SELECT attname FROM pg_attribute a WHERE a.attrelid=c.oid AND attnum>0 AND NOT attisdropped AND has_column_privilege(r.role,c.oid,a.attname,'UPDATE') ORDER BY attname))
 FROM pg_class c CROSS JOIN (VALUES('anon'),('authenticated'))r(role)
 WHERE c.oid IN (to_regclass('public.documentos'),to_regclass('public.exames_catalogo'))
 UNION ALL SELECT 'index:'||indexname,jsonb_build_object('definition',indexdef) FROM pg_indexes WHERE schemaname='public' AND tablename='documentos'
) SELECT identity,detail FROM entries),expected AS
(SELECT * FROM jsonb_to_recordset('[{"identity":"relation:storage.objects","detail":{"rls":true,"options":null}},{"identity":"relation:vw_dashboard_documentos","detail":{"rls":false,"options":["security_invoker=true"]}},{"identity":"relation:documentos","detail":{"rls":true,"options":null}},{"identity":"relation:exames_catalogo","detail":{"rls":true,"options":null}},{"identity":"policy:storage.objects.documentos_storage_select","detail":{"check":null,"roles":"{authenticated}","using":"((bucket_id = ''documentos''::text) AND engmarq_private.can_access_documento(name))","command":"SELECT","permissive":"PERMISSIVE"}},{"identity":"policy:storage.objects.documentos_storage_insert","detail":{"check":"((bucket_id = ''documentos''::text) AND engmarq_private.can_access_documento(name, true))","roles":"{authenticated}","using":null,"command":"INSERT","permissive":"PERMISSIVE"}},{"identity":"policy:storage.objects.documentos_storage_update","detail":{"check":"((bucket_id = ''documentos''::text) AND engmarq_private.can_access_documento(name, true) AND (split_part(name, ''/''::text, 2) <> ''certificados''::text))","roles":"{authenticated}","using":"((bucket_id = ''documentos''::text) AND engmarq_private.can_access_documento(name, true) AND (split_part(name, ''/''::text, 2) <> ''certificados''::text))","command":"UPDATE","permissive":"PERMISSIVE"}},{"identity":"policy:storage.objects.documentos_storage_delete","detail":{"check":null,"roles":"{authenticated}","using":"((bucket_id = ''documentos''::text) AND engmarq_private.can_access_documento(name, true) AND (split_part(name, ''/''::text, 2) <> ''certificados''::text))","command":"DELETE","permissive":"PERMISSIVE"}},{"identity":"policy:storage.objects.documentos_tenant_select_guard","detail":{"check":null,"roles":"{public}","using":"((bucket_id <> ''documentos''::text) OR engmarq_private.can_access_documento(name))","command":"SELECT","permissive":"RESTRICTIVE"}},{"identity":"policy:storage.objects.documentos_tenant_insert_guard","detail":{"check":"((bucket_id <> ''documentos''::text) OR engmarq_private.can_access_documento(name, true))","roles":"{public}","using":null,"command":"INSERT","permissive":"RESTRICTIVE"}},{"identity":"policy:storage.objects.documentos_tenant_update_guard","detail":{"check":"((bucket_id <> ''documentos''::text) OR (engmarq_private.can_access_documento(name, true) AND (split_part(name, ''/''::text, 2) <> ''certificados''::text)))","roles":"{public}","using":"((bucket_id <> ''documentos''::text) OR (engmarq_private.can_access_documento(name, true) AND (split_part(name, ''/''::text, 2) <> ''certificados''::text)))","command":"UPDATE","permissive":"RESTRICTIVE"}},{"identity":"policy:storage.objects.documentos_tenant_delete_guard","detail":{"check":null,"roles":"{public}","using":"((bucket_id <> ''documentos''::text) OR (engmarq_private.can_access_documento(name, true) AND (split_part(name, ''/''::text, 2) <> ''certificados''::text)))","command":"DELETE","permissive":"RESTRICTIVE"}},{"identity":"policy:public.documentos.documentos_select","detail":{"check":null,"roles":"{authenticated}","using":"engmarq_private.can_access_documento_row(empresa_id)","command":"SELECT","permissive":"PERMISSIVE"}},{"identity":"policy:public.documentos.documentos_insert","detail":{"check":"engmarq_private.can_access_documento_row(empresa_id, true)","roles":"{authenticated}","using":null,"command":"INSERT","permissive":"PERMISSIVE"}},{"identity":"policy:public.documentos.documentos_update","detail":{"check":"engmarq_private.can_access_documento_row(empresa_id, true)","roles":"{authenticated}","using":"engmarq_private.can_access_documento_row(empresa_id, true)","command":"UPDATE","permissive":"PERMISSIVE"}},{"identity":"policy:public.documentos.documentos_delete","detail":{"check":null,"roles":"{authenticated}","using":"engmarq_private.can_access_documento_row(empresa_id, true)","command":"DELETE","permissive":"PERMISSIVE"}},{"identity":"policy:public.documentos.documentos_row_guard","detail":{"check":"engmarq_private.can_access_documento_row(empresa_id, true)","roles":"{authenticated}","using":"engmarq_private.can_access_documento_row(empresa_id)","command":"ALL","permissive":"RESTRICTIVE"}},{"identity":"policy:public.exames_catalogo.exames_catalogo_read","detail":{"check":null,"roles":"{authenticated}","using":"engmarq_private.can_read_exames_catalogo()","command":"SELECT","permissive":"PERMISSIVE"}},{"identity":"function:engmarq_private.can_access_documento_row(uuid,boolean)","detail":{"anon":false,"hash":"da9931f372128801950764253468435f","owner":"postgres","config":["search_path=\"\""],"definer":true,"volatility":"s","return_type":"boolean","authenticated":true,"owner_privileged":true,"anon_owner_member":false,"authenticated_owner_member":false}},{"identity":"function:engmarq_private.can_access_catalogos(uuid,boolean)","detail":{"anon":false,"hash":"bbcffb334e82a68dd20f4152ecbbd8c0","owner":"postgres","config":["search_path=\"\""],"definer":true,"volatility":"s","return_type":"boolean","authenticated":true,"owner_privileged":true,"anon_owner_member":false,"authenticated_owner_member":false}},{"identity":"function:engmarq_private.can_access_documento(text,boolean)","detail":{"anon":true,"hash":"6d5ca74fe93623469f3318b51685be1a","owner":"postgres","config":["search_path=\"\""],"definer":true,"volatility":"s","return_type":"boolean","authenticated":true,"owner_privileged":true,"anon_owner_member":false,"authenticated_owner_member":false}},{"identity":"function:engmarq_private.guard_documento_reference()","detail":{"anon":false,"hash":"f5d02cdb06330847d16d51eea1ffb154","owner":"postgres","config":["search_path=\"\""],"definer":true,"volatility":"v","return_type":"trigger","authenticated":false,"owner_privileged":true,"anon_owner_member":false,"authenticated_owner_member":false}},{"identity":"function:engmarq_private.guard_documento_metadata()","detail":{"anon":false,"hash":"3ae962f81d252f13e91f22314a58c4a6","owner":"postgres","config":["search_path=\"\""],"definer":true,"volatility":"v","return_type":"trigger","authenticated":false,"owner_privileged":true,"anon_owner_member":false,"authenticated_owner_member":false}},{"identity":"function:engmarq_private.guard_aso_write()","detail":{"anon":false,"hash":"e4f3c879afc8daa56f8e52fda70e6a8a","owner":"postgres","config":["search_path=\"\""],"definer":true,"volatility":"v","return_type":"trigger","authenticated":false,"owner_privileged":true,"anon_owner_member":false,"authenticated_owner_member":false}},{"identity":"function:engmarq_private.can_read_exames_catalogo()","detail":{"anon":false,"hash":"6b7b03a71c5db04ff26dbf4436d5f226","owner":"postgres","config":["search_path=\"\""],"definer":true,"volatility":"s","return_type":"boolean","authenticated":true,"owner_privileged":true,"anon_owner_member":false,"authenticated_owner_member":false}},{"identity":"trigger:guard_aso_write","detail":{"enabled":"O","definition":"CREATE TRIGGER guard_aso_write BEFORE INSERT OR UPDATE ON public.documentos FOR EACH ROW EXECUTE FUNCTION engmarq_private.guard_aso_write()"}},{"identity":"trigger:guard_documento_metadata","detail":{"enabled":"O","definition":"CREATE TRIGGER guard_documento_metadata BEFORE INSERT OR DELETE OR UPDATE ON public.documentos FOR EACH ROW EXECUTE FUNCTION engmarq_private.guard_documento_metadata()"}},{"identity":"trigger:guard_documento_reference","detail":{"enabled":"O","definition":"CREATE TRIGGER guard_documento_reference BEFORE INSERT OR UPDATE ON public.documentos FOR EACH ROW EXECUTE FUNCTION engmarq_private.guard_documento_reference()"}},{"identity":"trigger:trg_documento_status","detail":{"enabled":"O","definition":"CREATE TRIGGER trg_documento_status BEFORE INSERT OR UPDATE ON public.documentos FOR EACH ROW EXECUTE FUNCTION update_documento_status()"}},{"identity":"constraint:documentos_arquivo_path_check","detail":{"validated":true,"definition":"CHECK (((arquivo_path IS NULL) OR (arquivo_path ~ ((''^''::text || (empresa_id)::text) || ''/(certificados/)?[A-Za-z0-9_-]+\\.[A-Za-z0-9]+$''::text))))"}},{"identity":"constraint:documentos_colaborador_tenant_fkey","detail":{"validated":true,"definition":"FOREIGN KEY (empresa_id, colaborador_id) REFERENCES colaboradores(empresa_id, id)"}},{"identity":"constraint:documentos_empresa_id_fkey","detail":{"validated":true,"definition":"FOREIGN KEY (empresa_id) REFERENCES empresas(id)"}},{"identity":"constraint:documentos_pkey","detail":{"validated":true,"definition":"PRIMARY KEY (id)"}},{"identity":"constraint:documentos_resultado_aso_check","detail":{"validated":true,"definition":"CHECK (((resultado_aso IS NULL) OR (resultado_aso = ANY (ARRAY[''apto''::text, ''apto_com_restricao''::text, ''inapto''::text]))))"}},{"identity":"constraint:documentos_subtipo_exame_check","detail":{"validated":true,"definition":"CHECK (((subtipo_exame = ANY (ARRAY[''admissional''::text, ''periodico''::text, ''mudanca_risco''::text, ''retorno_trabalho''::text, ''demissional''::text])) OR (subtipo_exame IS NULL)))"}},{"identity":"constraint:documentos_tipo_id_fkey","detail":{"validated":true,"definition":"FOREIGN KEY (tipo_id) REFERENCES documento_tipos(id)"}},{"identity":"view:vw_dashboard_documentos","detail":{"definition":" SELECT d.empresa_id,\n    dt.nome AS tipo_nome,\n    d.titulo,\n    d.vencimento,\n        CASE\n            WHEN (d.vencimento IS NULL) THEN ''vigente''::text\n            WHEN (d.vencimento <\n            CASE\n                WHEN (lower(btrim(dt.nome)) = ''aso''::text) THEN ((CURRENT_TIMESTAMP AT TIME ZONE ''America/Sao_Paulo''::text))::date\n                ELSE CURRENT_DATE\n            END) THEN ''vencido''::text\n            WHEN (d.vencimento <= (\n            CASE\n                WHEN (lower(btrim(dt.nome)) = ''aso''::text) THEN ((CURRENT_TIMESTAMP AT TIME ZONE ''America/Sao_Paulo''::text))::date\n                ELSE CURRENT_DATE\n            END +\n            CASE\n                WHEN (lower(btrim(dt.nome)) = ''aso''::text) THEN 30\n                ELSE 60\n            END)) THEN ''vencendo''::text\n            ELSE ''vigente''::text\n        END AS status_calculado,\n    (d.vencimento -\n        CASE\n            WHEN (lower(btrim(dt.nome)) = ''aso''::text) THEN ((CURRENT_TIMESTAMP AT TIME ZONE ''America/Sao_Paulo''::text))::date\n            ELSE CURRENT_DATE\n        END) AS dias_restantes\n   FROM (documentos d\n     JOIN documento_tipos dt ON ((dt.id = d.tipo_id)));"}},{"identity":"column:documentos.id","detail":{"type":"uuid","nullable":false}},{"identity":"column:documentos.empresa_id","detail":{"type":"uuid","nullable":false}},{"identity":"column:documentos.tipo_id","detail":{"type":"uuid","nullable":false}},{"identity":"column:documentos.titulo","detail":{"type":"text","nullable":false}},{"identity":"column:documentos.numero","detail":{"type":"text","nullable":true}},{"identity":"column:documentos.emissao","detail":{"type":"date","nullable":true}},{"identity":"column:documentos.vencimento","detail":{"type":"date","nullable":true}},{"identity":"column:documentos.arquivo_url","detail":{"type":"text","nullable":true}},{"identity":"column:documentos.status","detail":{"type":"doc_status","nullable":false}},{"identity":"column:documentos.observacoes","detail":{"type":"text","nullable":true}},{"identity":"column:documentos.created_at","detail":{"type":"timestamp with time zone","nullable":true}},{"identity":"column:documentos.colaborador_id","detail":{"type":"uuid","nullable":true}},{"identity":"column:documentos.subtipo_exame","detail":{"type":"text","nullable":true}},{"identity":"column:documentos.exames_realizados","detail":{"type":"text[]","nullable":true}},{"identity":"column:documentos.arquivo_path","detail":{"type":"text","nullable":true}},{"identity":"column:documentos.resultado_aso","detail":{"type":"text","nullable":true}},{"identity":"grant:documentos.anon","detail":{"delete":false,"insert":[],"select":false,"update":[]}},{"identity":"grant:documentos.authenticated","detail":{"delete":true,"insert":["arquivo_path","colaborador_id","emissao","empresa_id","exames_realizados","numero","observacoes","resultado_aso","subtipo_exame","tipo_id","titulo","vencimento"],"select":true,"update":["arquivo_path","colaborador_id","emissao","exames_realizados","numero","observacoes","resultado_aso","subtipo_exame","tipo_id","titulo","vencimento"]}},{"identity":"grant:exames_catalogo.anon","detail":{"delete":false,"insert":[],"select":false,"update":[]}},{"identity":"grant:exames_catalogo.authenticated","detail":{"delete":false,"insert":[],"select":true,"update":[]}},{"identity":"index:documentos_pkey","detail":{"definition":"CREATE UNIQUE INDEX documentos_pkey ON public.documentos USING btree (id)"}},{"identity":"index:idx_documentos_empresa","detail":{"definition":"CREATE INDEX idx_documentos_empresa ON public.documentos USING btree (empresa_id)"}},{"identity":"index:idx_documentos_vencimento","detail":{"definition":"CREATE INDEX idx_documentos_vencimento ON public.documentos USING btree (vencimento)"}},{"identity":"index:idx_documentos_colaborador_id","detail":{"definition":"CREATE INDEX idx_documentos_colaborador_id ON public.documentos USING btree (colaborador_id) WHERE (colaborador_id IS NOT NULL)"}},{"identity":"index:idx_documentos_aso_tenant_tipo_colaborador","detail":{"definition":"CREATE INDEX idx_documentos_aso_tenant_tipo_colaborador ON public.documentos USING btree (empresa_id, tipo_id, colaborador_id)"}}]'::jsonb)e(identity text,detail jsonb))
SELECT coalesce(a.identity,e.identity) AS "CHECK",
CASE WHEN a.identity IS NULL THEN 'ausente' WHEN e.identity IS NULL THEN 'objeto adicional' WHEN a.detail IS DISTINCT FROM e.detail THEN 'contrato divergente' ELSE 'contrato conferido' END AS "RESULTADO",
CASE WHEN a.detail IS DISTINCT FROM e.detail THEN 'BLOQUEIO' ELSE 'OK' END AS "STATUS"
FROM actual a FULL JOIN expected e USING(identity) ORDER BY 1;

-- Authorization of the auditor: filtered tenant snapshots never prove global preservation.
SELECT 'Auditor integral' AS "CHECK",current_user AS "RESULTADO",
CASE WHEN EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN 'OK' ELSE 'BLOQUEIO' END AS "STATUS";

WITH asos AS (SELECT d.* FROM public.documentos d JOIN public.documento_tipos t ON t.id=d.tipo_id WHERE lower(btrim(t.nome))='aso'),
checks(label,n,expected) AS (
 SELECT 'Documentos preservados',count(*),12 FROM public.documentos
 UNION ALL SELECT 'ASOs preservados',count(*),4 FROM asos
 UNION ALL SELECT 'Admissionais preservados',count(*),3 FROM asos WHERE subtipo_exame='admissional'
 UNION ALL SELECT 'Periódicos preservados',count(*),1 FROM asos WHERE subtipo_exame='periodico'
 UNION ALL SELECT 'ASOs com colaborador válido',count(*),4 FROM asos d JOIN public.colaboradores c ON c.id=d.colaborador_id AND c.empresa_id=d.empresa_id
 UNION ALL SELECT 'ASOs com observações legadas intactas',count(*),4 FROM asos WHERE observacoes='Apto'
 UNION ALL SELECT 'ASOs com procedimentos preenchidos',count(*),3 FROM asos WHERE cardinality(exames_realizados)>0
 UNION ALL SELECT 'ASOs com procedimentos vazios',count(*),1 FROM asos WHERE cardinality(exames_realizados)=0
 UNION ALL SELECT 'Catálogo preservado',count(*),27 FROM public.exames_catalogo
 UNION ALL SELECT 'ASOs com arquivo',count(*),1 FROM asos WHERE arquivo_path IS NOT NULL OR arquivo_url IS NOT NULL
 UNION ALL SELECT 'ASOs sem arquivo',count(*),3 FROM asos WHERE arquivo_path IS NULL AND arquivo_url IS NULL
 UNION ALL SELECT 'Não-ASOs associados a colaborador',count(*),2 FROM public.documentos d JOIN public.documento_tipos t ON t.id=d.tipo_id
 WHERE lower(btrim(t.nome))<>'aso' AND d.colaborador_id IS NOT NULL
 UNION ALL SELECT 'Cross-tenant/colaborador inválido',count(*),0 FROM public.documentos d LEFT JOIN public.colaboradores c ON c.id=d.colaborador_id
 WHERE d.colaborador_id IS NOT NULL AND (c.id IS NULL OR c.empresa_id<>d.empresa_id)
 UNION ALL SELECT 'Bucket privado/limite/MIME',count(*),1 FROM storage.buckets WHERE id='documentos' AND NOT public AND file_size_limit=10485760
 AND cardinality(allowed_mime_types)=7 AND allowed_mime_types @> ARRAY['application/pdf','application/msword',
 'application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel',
 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','image/jpeg','image/png']
 UNION ALL SELECT 'Referências canônicas sem objeto',count(*),0 FROM public.documentos d WHERE arquivo_path IS NOT NULL AND NOT EXISTS
 (SELECT 1 FROM storage.objects o WHERE o.bucket_id='documentos' AND o.name=d.arquivo_path)
 UNION ALL SELECT 'Resultado novo continua NULL no legado',count(*),4 FROM asos WHERE resultado_aso IS NULL
)
SELECT label AS "CHECK",n::text||' / esperado '||expected::text AS "RESULTADO",CASE WHEN n=expected THEN 'OK' ELSE 'BLOQUEIO' END AS "STATUS" FROM checks ORDER BY label;

-- Fingerprints contain no row contents. Compare exactly between preflight and postflight.
SELECT 'Preservação: documentos (sem coluna nova)' AS "CHECK",
md5(coalesce(jsonb_agg(to_jsonb(d)-'resultado_aso' ORDER BY d.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.documentos d
UNION ALL SELECT 'Preservação: catálogo',md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.id)::text,'[]')),'ATENÇÃO' FROM public.exames_catalogo c
UNION ALL SELECT 'Preservação: objetos documentos',md5(coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.id)::text,'[]')),'ATENÇÃO' FROM storage.objects o WHERE bucket_id='documentos'
UNION ALL SELECT 'Preservação: tipos documentais',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.id)::text,'[]')),'ATENÇÃO' FROM public.documento_tipos t;
COMMIT;
